-- 985Fitness schema v1.6
-- MySQL 8.x / InnoDB / utf8mb4
-- Primary keys are generated by the application with a Snowflake-style ID.
-- Create and select the database before running this Flyway migration.

SET NAMES utf8mb4;

CREATE TABLE t_985fitness_user (
    id              BIGINT       NOT NULL COMMENT '雪花ID',
    openid          VARCHAR(64)  NOT NULL COMMENT '微信openid（小程序用户唯一标识）',
    unionid         VARCHAR(64)      NULL COMMENT '微信unionid（多平台打通用）',
    nickname        VARCHAR(60)      NULL COMMENT '微信昵称',
    avatar          VARCHAR(500)     NULL COMMENT '头像URL',
    phone           VARCHAR(20)      NULL COMMENT '手机号（加密存储）',
    gender          TINYINT          NULL COMMENT '性别：0未知 1男 2女',
    birthday        DATE             NULL COMMENT '生日',
    status          TINYINT      NOT NULL DEFAULT 1 COMMENT '状态：1正常 0冻结 2注销',
    remark          VARCHAR(500)     NULL COMMENT '后台备注',
    register_time   DATETIME     NOT NULL COMMENT '注册时间',
    last_login_time DATETIME         NULL COMMENT '最后登录时间',
    create_time     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    deleted         TINYINT      NOT NULL DEFAULT 0 COMMENT '逻辑删除：0否 1是',
    PRIMARY KEY (id),
    UNIQUE KEY uk_user_openid (openid),
    KEY idx_user_phone (phone),
    KEY idx_user_register_time (register_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户表（微信小程序会员）';

CREATE TABLE t_985fitness_admin (
    id              BIGINT       NOT NULL,
    username        VARCHAR(50)  NOT NULL COMMENT '登录账号',
    password        VARCHAR(255) NOT NULL COMMENT 'BCrypt密码摘要',
    real_name       VARCHAR(50)      NULL COMMENT '真实姓名',
    phone           VARCHAR(20)      NULL COMMENT '手机号',
    avatar          VARCHAR(500)     NULL COMMENT '头像URL',
    role            TINYINT      NOT NULL COMMENT '角色：1超级管理员 2店长 3运营 4财务',
    store_id        BIGINT           NULL COMMENT '管辖门店ID，NULL表示全部门店',
    status          TINYINT      NOT NULL DEFAULT 1 COMMENT '状态：1启用 0停用',
    last_login_ip   VARCHAR(64)      NULL COMMENT '最后登录IP',
    last_login_time DATETIME         NULL COMMENT '最后登录时间',
    create_time     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    deleted         TINYINT      NOT NULL DEFAULT 0 COMMENT '逻辑删除：0否 1是',
    PRIMARY KEY (id),
    UNIQUE KEY uk_admin_username (username),
    KEY idx_admin_store (store_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='管理后台管理员表';

CREATE TABLE t_985fitness_store (
    id              BIGINT        NOT NULL,
    name            VARCHAR(100)  NOT NULL COMMENT '门店名称',
    short_name      VARCHAR(50)       NULL COMMENT '门店简称',
    address         VARCHAR(200)      NULL COMMENT '详细地址',
    longitude       DECIMAL(10, 6)    NULL COMMENT '经度（高德坐标系）',
    latitude        DECIMAL(10, 6)    NULL COMMENT '纬度（高德坐标系）',
    phone           VARCHAR(20)       NULL COMMENT '门店电话',
    service_phone   VARCHAR(20)       NULL COMMENT '客服电话',
    wifi_name       VARCHAR(50)       NULL COMMENT 'WIFI SSID',
    wifi_password   VARCHAR(50)       NULL COMMENT 'WIFI密码',
    cover           JSON              NULL COMMENT '首页图片信息',
    intro           TEXT              NULL COMMENT '门店介绍',
    photos          JSON              NULL COMMENT '到店指引照片数组',
    sort_order      INT           NOT NULL DEFAULT 0 COMMENT '排序权重',
    create_time     DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time     DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    deleted         TINYINT       NOT NULL DEFAULT 0 COMMENT '逻辑删除：0否 1是',
    PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='门店表';

CREATE TABLE t_985fitness_coach (
