    phone           VARCHAR(20)      NULL COMMENT '手机号',
    specialties     JSON             NULL COMMENT '专长标签数组',
    intro           TEXT             NULL COMMENT '个人简介',
    price           BIGINT       NOT NULL DEFAULT 0 COMMENT '课时费，单位分',
    status          TINYINT      NOT NULL DEFAULT 1 COMMENT '状态：1可预约 0休息 2离职',
    create_time     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
