    PRIMARY KEY (id),
    UNIQUE KEY uk_coach_user (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='教练和助教表';

