    status          TINYINT   NOT NULL DEFAULT 1 COMMENT '状态：1可预约 0已满',
    create_time     DATETIME  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time     DATETIME  NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    deleted         TINYINT   NOT NULL DEFAULT 0 COMMENT '逻辑删除：0否 1是',
    PRIMARY KEY (id),
    KEY idx_schedule_coach_time (coach_id, start_time),
    KEY idx_schedule_store_time (store_id, start_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='教练排班时段表';

CREATE TABLE t_985fitness_booking (
    id              BIGINT       NOT NULL,
    user_id         BIGINT       NOT NULL COMMENT '用户ID',
    schedule_id     BIGINT       NOT NULL COMMENT '排班ID',
    order_id        BIGINT           NULL COMMENT '关联订单ID',
    coach_id        BIGINT           NULL COMMENT '教练或助教ID',
    payment_method  VARCHAR(20)      NULL COMMENT '支付方式：WECHAT/STORED_VALUE/COUPON',
    amount          BIGINT       NOT NULL DEFAULT 0 COMMENT '实付金额，单位分',
