    id              BIGINT       NOT NULL,
    store_id        BIGINT       NOT NULL COMMENT '门店ID',
    title           VARCHAR(100) NOT NULL COMMENT '公告标题',
    summary         VARCHAR(200)     NULL COMMENT '摘要',
    content         MEDIUMTEXT       NULL COMMENT '公告全文',
    images          JSON             NULL COMMENT '图片数组',
    create_time     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='门店公告表';

CREATE TABLE t_985fitness_assistant_application (
    id                  BIGINT       NOT NULL,
    user_id             BIGINT       NOT NULL COMMENT '申请用户ID',
    intro               TEXT             NULL COMMENT '个人简介',
    specialties         JSON             NULL COMMENT '专长标签数组',
    available_time      JSON             NULL COMMENT '可预约时间说明',
    images              JSON             NULL COMMENT '运动照片数组',
    videos              JSON             NULL COMMENT '运动视频数组',
    status              TINYINT       NOT NULL DEFAULT 1 COMMENT '状态：1待审 2通过 3拒绝',
    reject_reason       VARCHAR(200)      NULL COMMENT '拒绝原因',
    review_by           BIGINT            NULL COMMENT '审核管理员ID',
    review_time         DATETIME          NULL COMMENT '审核时间',
    last_apply_time     DATETIME      NOT NULL COMMENT '最近申请时间',
    create_time         DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time         DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    KEY idx_assistant_application_user (user_id),
    KEY idx_assistant_application_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助教申请表';

CREATE TABLE t_985fitness_external_coupon (
    id              BIGINT       NOT NULL,
    platform        VARCHAR(16)  NOT NULL COMMENT '平台：DOUYIN/MEITUAN',
    code            VARCHAR(64)  NOT NULL COMMENT '平台券码',
    sku_id          VARCHAR(64)      NULL COMMENT '平台商品ID',
    sku_name        VARCHAR(200)     NULL COMMENT '商品名称快照',
    face_value      BIGINT           NULL COMMENT '面值，单位分',
    user_phone      VARCHAR(20)      NULL COMMENT '购券手机号',
    verify_status   TINYINT      NOT NULL DEFAULT 1 COMMENT '状态：1待核销 2已核销 3已退券',
    verify_time     DATETIME         NULL COMMENT '核销时间',
    verify_by       BIGINT           NULL COMMENT '核销员工ID',
    store_id        BIGINT           NULL COMMENT '核销门店ID',
    raw_response    JSON             NULL COMMENT '平台原始响应',
    create_time     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_external_coupon_platform_code (platform, code),
    KEY idx_external_coupon_platform_status (platform, verify_status),
    KEY idx_external_coupon_store_time (store_id, verify_time)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='抖音和美团券核销记录表';

CREATE TABLE t_985fitness_product (
    id              BIGINT       NOT NULL,
    name            VARCHAR(100) NOT NULL COMMENT '商品名称',
    category        VARCHAR(50)  NOT NULL COMMENT '商品分类',
    price           BIGINT       NOT NULL COMMENT '售价，单位分',
    stock           INT          NOT NULL DEFAULT 0 COMMENT '库存',
    image_url       VARCHAR(500)     NULL COMMENT '商品图片URL',
    status          TINYINT      NOT NULL DEFAULT 0 COMMENT '状态：1上架 0下架',
    create_time     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    deleted         TINYINT      NOT NULL DEFAULT 0 COMMENT '逻辑删除：0否 1是',
    PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='商品销售预留表';
